// ---------------------------------------------------------------
// Utilidades de hábitos: normalización y estadísticas.
// ---------------------------------------------------------------
const normalizar = (t) => String(t || '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .trim().toLowerCase();

const esActivo = (v) => v === true || ['si', 'true', '1', 'yes', 'activo'].includes(normalizar(v));

function leerNodo(nombre) {
  try {
    return $(nombre).all().map((i) => i.json);
  } catch (error) {
    return [];
  }
}

function habitosActivos(filas) {
  return filas
    .filter((h) => h && h.habito && esActivo(h.activo))
    .map((h) => ({
      habito: normalizar(h.habito),
      descripcion: h.descripcion || '',
      metaSemanal: Math.min(7, Math.max(1, Number(h.meta_semanal) || 7)),
    }));
}

function registrosDelChat(filas, chatId) {
  return filas
    .filter((r) => r && r.habito && r.fecha)
    .filter((r) => !chatId || String(r.chat_id) === String(chatId))
    .map((r) => ({ ...r, habito: normalizar(r.habito), fecha: String(r.fecha).slice(0, 10) }));
}

// Porcentaje de cumplimiento en los últimos "dias" días (incluido hoy).
function calcularEstadisticas(habitos, registros, dias) {
  const desde = $now.minus({ days: dias - 1 }).toFormat('yyyy-MM-dd');
  const hasta = $now.toFormat('yyyy-MM-dd');
  return habitos.map((h) => {
    const fechas = new Set(registros
      .filter((r) => r.habito === h.habito && r.fecha >= desde && r.fecha <= hasta)
      .map((r) => r.fecha));
    const objetivo = Math.max(1, Math.round((h.metaSemanal * dias) / 7));
    const porcentaje = Math.min(100, Math.round((fechas.size / objetivo) * 100));
    return { habito: h.habito, diasCumplidos: fechas.size, objetivo, porcentaje };
  });
}

function barra(porcentaje) {
  const llenos = Math.round(porcentaje / 10);
  return '#'.repeat(llenos) + '-'.repeat(10 - llenos);
}

function textoEstadisticas(estadisticas, dias) {
  if (estadisticas.length === 0) return 'No hay hábitos activos en la hoja Habitos.';
  const media = Math.round(estadisticas.reduce((s, e) => s + e.porcentaje, 0) / estadisticas.length);
  const lineas = estadisticas
    .sort((a, b) => b.porcentaje - a.porcentaje)
    .map((e) => `${barra(e.porcentaje)} ${String(e.porcentaje).padStart(3)}%  ${e.habito} (${e.diasCumplidos}/${e.objetivo} días)`);
  return [`Cumplimiento de los últimos ${dias} días`, '', ...lineas, '', `Media global: ${media}%`].join('\n');
}

// Resumen semanal para el chat configurado.
const config = $('Configuración').first().json;
const habitos = habitosActivos(leerNodo('Leer hábitos'));
const registros = registrosDelChat(leerNodo('Leer registro'), config.chatId);
const estadisticas = calcularEstadisticas(habitos, registros, 7);
const mejor = [...estadisticas].sort((a, b) => b.porcentaje - a.porcentaje)[0];
const peor = [...estadisticas].sort((a, b) => a.porcentaje - b.porcentaje)[0];

const lineas = ['Resumen semanal de hábitos', '', textoEstadisticas(estadisticas, 7)];
if (mejor && peor && mejor.habito !== peor.habito) {
  lineas.push('', `Tu hábito más constante: ${mejor.habito}.`, `A reforzar la próxima semana: ${peor.habito}.`);
}
return [{ json: { chatId: String(config.chatId || ''), estadisticas, respuesta: lineas.join('\n') } }];
